CREATE DATABASE /*!32312 IF NOT EXISTS*/`sisvot_bd` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci */;

USE `sisvot_bd`;

/*Table structure for table `candidatos` */

DROP TABLE IF EXISTS `candidatos`;

CREATE TABLE `candidatos` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `numero` varchar(3) NOT NULL,
  `photo` char(150) DEFAULT 'default',
  `studentId` char(30) CHARACTER SET utf8 COLLATE utf8_spanish_ci NOT NULL,
  `color` varchar(10) DEFAULT NULL,
  `partido` varchar(100) DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'Personero',
  PRIMARY KEY (`id`,`numero`),
  KEY `fk_candidatosvot_alumnos1_idx` (`studentId`),
  CONSTRAINT `fk_candidatosvot_alumnos1` FOREIGN KEY (`studentId`) REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8 COLLATE=utf8_bin;

